const mixs=(a,b,u)=>{const f=s=>s.charAt(0)=='#'?hx(s):s.match(/\d+/g).map(Number);const p=f(a),q=f(b);return'rgb('+Math.round(p[0]+(q[0]-p[0])*u)+','+Math.round(p[1]+(q[1]-p[1])*u)+','+Math.round(p[2]+(q[2]-p[2])*u)+')'};
const INTRO="Ottocento, dall’alba alla notte. Parti dalle risaie della pianura padana, dove le mondine lavorano con i piedi nell’acqua; poi Pavia, dove Alessandro Volta costruisce la prima pila elettrica; Genova, da dove salpano Garibaldi e i suoi Mille e, più tardi, gli emigranti diretti in America; Firenze, capitale d’Italia per pochi anni, con il suo grande mercato e la cucina di casa Artusi. A mezzogiorno Napoli, con il Vesuvio che fuma e la pizza che esce dal forno; nel primo pomeriggio la stazione, con il treno a vapore, il telegrafo e l’orologio; poi Pontecchio, dove un ragazzo di ventun anni fa suonare un campanello senza fili; di sera Milano, con la Galleria, il teatro La Scala e il maestro Verdi, e di notte la Torre Eiffel, illuminata, a Parigi. Il tempo qui si piega: contadine, scienziati, soldati volontari, cuoche, pizzaioli, ferrovieri, inventori e musicisti di ogni anno del secolo ti vengono incontro.";
const NZ=[4, 4, 5, 4, 4, 4, 4, 5];
